<style>
  .co-page{padding:22px}.co-hero{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:27px 30px;margin-bottom:18px;border-radius:18px;color:#fff;background:linear-gradient(115deg,#0b5e89,#138fb4 62%,#16aaa5);box-shadow:0 13px 30px rgba(20,91,122,.16)}.co-hero__main{display:flex;align-items:center;gap:18px}.co-hero__icon{display:grid;place-items:center;width:62px;height:62px;border:1px solid rgba(255,255,255,.3);border-radius:16px;background:rgba(255,255,255,.11);font-size:27px}.co-hero h1{margin:2px 0 5px;font-size:28px;font-weight:800}.co-hero p{margin:0;opacity:.94}.co-eyebrow{font-size:12px;font-weight:800;letter-spacing:1.2px}.co-hero .btn{border-radius:9px;font-weight:800}
  .co-card{overflow:visible;margin-bottom:18px;border:1px solid #d4e5ed;border-radius:16px;background:#fff;box-shadow:0 8px 22px rgba(29,76,99,.06)}.co-head{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:16px 20px;border-bottom:1px solid #d4e5ed;border-radius:16px 16px 0 0;background:#eef9fc}.co-heading{display:flex;align-items:center;gap:12px}.co-heading>i{display:grid;place-items:center;width:39px;height:39px;border-radius:11px;color:#0788b7;background:#d9f3f8}.co-head h2{margin:0;color:#0b3554;font-size:18px;font-weight:800}.co-head p{margin:2px 0 0;color:#65839a;font-size:13px}.co-count{padding:6px 10px;border-radius:20px;color:#08799d;background:#e1f6fa;font-size:11px;font-weight:800}
  .co-filters{display:grid;grid-template-columns:repeat(4,minmax(150px,1fr));gap:12px;padding:18px 20px}.co-field label{display:block;margin-bottom:5px;color:#244a63;font-size:11px;font-weight:800;text-transform:uppercase}.co-field .form-control{height:40px;border-color:#c8dce5;border-radius:8px}.co-filter-actions{display:flex;align-items:flex-end;gap:8px}.co-filter-actions .btn{height:40px;border-radius:8px;font-weight:700}.co-table-wrap{padding:6px 18px 12px;overflow-x:auto}.co-table{min-width:1080px;margin:0}.co-table thead th{padding:12px;background:#f1f6f8;color:#173f5c;border-bottom:1px solid #d6e3e9;font-size:11px;text-transform:uppercase}.co-table td{padding:13px 12px;vertical-align:middle;border-bottom:1px solid #e2ebef;color:#294a61}.co-name{display:block;color:#073f66;font-weight:800}.co-meta{display:block;margin-top:3px;color:#7890a1;font-size:11px}.co-badge{display:inline-block;padding:5px 9px;border-radius:18px;color:#087b69;background:#e0f6f0;font-size:11px;font-weight:800}.co-actions{display:flex;gap:7px;white-space:nowrap}.co-actions .btn{border-radius:8px;font-size:11px;font-weight:800}.co-empty{padding:48px!important;text-align:center;color:#718c9e}.co-footer{display:flex;align-items:center;justify-content:space-between;padding:14px 20px;border-top:1px solid #dce8ed;color:#6d8799}.co-footer .pagination{margin:0}
  .co-stats{display:grid;grid-template-columns:repeat(5,1fr);gap:11px;margin-bottom:16px}.co-stat{padding:14px 16px;border:1px solid #d5e5ec;border-radius:12px;background:#fff}.co-stat strong{display:block;color:#103d5c;font-size:20px}.co-stat span{color:#738da0;font-size:11px}.co-bed-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:13px;padding:18px}.co-bed{position:relative;padding:16px;border:1px solid #d7e5eb;border-left:5px solid #27ae75;border-radius:12px;background:#fbfdfe}.co-bed.is-occupied{border-left-color:#e05454}.co-bed.is-preparation{border-left-color:#e6a722}.co-bed.is-disinfection{border-left-color:#8b7f9e}.co-bed h3{margin:0 0 5px;color:#0c4265;font-size:16px;font-weight:800}.co-bed__state{position:absolute;top:13px;right:13px;padding:4px 8px;border-radius:16px;background:#edf6f8;color:#416b82;font-size:10px;font-weight:800}.co-bed__patient{min-height:42px;margin:12px 0;padding:10px;border-radius:9px;background:#eef7fa;color:#31576f}.co-bed__actions{display:flex;gap:7px;flex-wrap:wrap}.co-bed__actions .btn{border-radius:8px;font-size:11px;font-weight:800}
  @media(max-width:1050px){.co-filters{grid-template-columns:repeat(2,1fr)}.co-bed-grid{grid-template-columns:repeat(2,1fr)}.co-stats{grid-template-columns:repeat(3,1fr)}}@media(max-width:650px){.co-page{padding:12px}.co-hero{padding:22px 18px;align-items:flex-start;flex-direction:column}.co-hero h1{font-size:23px}.co-filters,.co-bed-grid,.co-stats{grid-template-columns:1fr}.co-footer{align-items:flex-start;flex-direction:column;gap:10px}}
</style>
<style>
  /* Densidad clínica V3: patrón compacto, legible y reutilizable. */
  .co-page{padding:13px}.co-hero{gap:13px;padding:14px 18px;margin-bottom:11px;border-radius:12px;box-shadow:0 7px 18px rgba(20,91,122,.11)}.co-hero__main{gap:11px}.co-hero__icon{width:44px;height:44px;border-radius:10px;font-size:19px}.co-hero h1{margin:1px 0 2px;font-size:21px}.co-hero p{font-size:11.5px}.co-eyebrow{font-size:9.5px;letter-spacing:.9px}.co-hero .btn{min-height:34px!important;font-size:12px}
  .co-card{margin-bottom:11px;border-radius:11px;box-shadow:0 5px 16px rgba(29,76,99,.055)}.co-head{gap:9px;padding:8px 12px;border-radius:11px 11px 0 0}.co-heading{gap:8px}.co-heading>i{width:30px;height:30px;border-radius:8px;font-size:13px}.co-head h2{font-size:14px}.co-head p{margin-top:1px;font-size:10.5px}.co-count{padding:4px 8px;font-size:9.5px}
  .co-filters{gap:10px;padding:13px 16px}.co-field label{margin-bottom:4px;font-size:10px}.co-field .form-control,.co-filter-actions .btn{height:36px}.co-table-wrap{padding:4px 14px 10px}.co-table thead th{padding:9px 10px;font-size:10px}.co-table td{padding:10px}.co-meta,.co-badge,.co-actions .btn{font-size:10px}.co-empty{padding:32px!important}.co-footer{padding:10px 16px}
  .co-stats{gap:9px;margin-bottom:13px}.co-stat{padding:11px 13px}.co-stat strong{font-size:18px}.co-bed-grid{gap:10px;padding:14px}.co-bed{padding:13px}.co-bed h3{font-size:14px}.co-bed__patient{min-height:36px;margin:9px 0;padding:8px}
  @media(max-width:650px){.co-page{padding:9px}.co-hero{padding:13px 12px}.co-hero h1{font-size:19.5px}}
</style>
